# HPLT PowerPoint deck builder — populates AhaMo's template with a session's data.
# Pure function build_deck(payload, template_path) -> pptx bytes.
import io, base64, os
from pptx import Presentation
from pptx.util import Inches, Pt
from pptx.dml.color import RGBColor
from pptx.enum.text import PP_ALIGN, MSO_AUTO_SIZE, MSO_ANCHOR
from pptx.enum.shapes import MSO_SHAPE
from pptx.chart.data import CategoryChartData
from pptx.enum.chart import XL_CHART_TYPE, XL_LABEL_POSITION, XL_LEGEND_POSITION
from PIL import Image

MODEL = [{'key': 'mindset', 'name': 'Team mindset', 'colour': '#8DC640', 'desc': 'How much team members have a shared direction and consistently pull in that same direction.', 'subs': [{'name': 'Know where the team is headed', 'items': [{'n': 1, 't': 'Share clear and compelling team goals'}, {'n': 2, 't': 'Use clear metrics to track performance against team goals'}, {'n': 3, 't': 'Share a clear view of what the team stands for'}]}, {'name': 'Pull in the same direction', 'items': [{'n': 4, 't': 'Prioritise collective goals over personal goals'}, {'n': 5, 't': "Share accountability for the team's performance"}, {'n': 6, 't': 'Focus on outcomes instead of politics or power dynamics'}]}]}, {'key': 'relationships', 'name': 'Valued relationships', 'colour': '#2295A0', 'desc': 'How much team members share mutual respect, show genuine care, and feel safe to be themselves.', 'subs': [{'name': 'Embrace diverse thinking', 'items': [{'n': 7, 't': 'Seek and celebrate different perspectives'}, {'n': 8, 't': 'Share mistakes, concerns, and different viewpoints without fear of being judged'}, {'n': 9, 't': 'Handle mistakes constructively instead of playing a blame game'}]}, {'name': 'Show genuine care for one another', 'items': [{'n': 10, 't': 'Actively look out for and support one another'}, {'n': 11, 't': 'Develop each other and help one another to grow'}, {'n': 12, 't': 'Praise and celebrate each other'}]}, {'name': 'Share mutual respect', 'items': [{'n': 13, 't': 'Truly listen to one another'}, {'n': 14, 't': 'Trust other team members to do their jobs well'}, {'n': 15, 't': 'Trust the positive intent of other team members'}, {'n': 16, 't': "Adapt to each other's needs and preferences"}]}]}, {'key': 'learning', 'name': 'Continuous learning', 'colour': '#2484C6', 'desc': 'How well the team uses feedback, conflict, reflection, and risks to keep improving every day.', 'subs': [{'name': 'Learn from successes and failures', 'items': [{'n': 17, 't': 'Celebrate and learn from team successes'}, {'n': 18, 't': 'Regularly review and learn from team performance'}, {'n': 19, 't': 'Have processes to gather, listen, and act on feedback'}, {'n': 20, 't': 'Share knowledge openly and effectively with one another'}, {'n': 21, 't': 'Embrace risk and change as potential ways to improve performance'}]}, {'name': 'Use conflict constructively', 'items': [{'n': 22, 't': 'Share constructive feedback to help each other develop'}, {'n': 23, 't': 'Disagree openly with one another and use conflict to come up with better solutions'}]}]}, {'key': 'processes', 'name': 'Frictionless processes', 'colour': '#32449C', 'desc': 'How well the team uses processes and structures that help them be efficient and make great decisions.', 'subs': [{'name': 'Share effective ways of working', 'items': [{'n': 24, 't': 'Share clear ways of working'}, {'n': 25, 't': 'Coordinate tasks across the team in a seamless way'}, {'n': 26, 't': 'Have efficient and effective processes to help us perform'}]}, {'name': 'Make smart decisions', 'items': [{'n': 27, 't': 'Have complementary strengths and areas of expertise'}, {'n': 28, 't': 'Use the diverse expertise in the team to make great decisions'}, {'n': 29, 't': 'Use outside-in perspectives to inform decisions'}, {'n': 30, 't': 'Have clear processes for making decisions'}]}, {'name': 'Know and play personal roles', 'items': [{'n': 31, 't': 'Have clear roles and responsibilities'}, {'n': 32, 't': 'Deliver on their personal roles'}, {'n': 33, 't': "Understand each other's areas and responsibilities"}]}, {'name': 'Manage time efficiently', 'items': [{'n': 34, 't': 'Have productive and well-run meetings'}, {'n': 35, 't': 'Focus the right amount of time on the right things'}]}]}, {'key': 'leadership', 'name': 'Strategic leadership', 'colour': '#20396D', 'desc': 'How well the team operate strategically and have far-reaching positive impact across the organisation.', 'subs': [{'name': 'Operate strategically', 'items': [{'n': 36, 't': 'Balance short-term operational priorities with long-term strategy'}, {'n': 37, 't': 'Make decisions that balance commercial and broader needs (e.g., culture, sustainability)'}, {'n': 38, 't': 'Empower the teams they lead to step up, so they can operate strategically'}]}, {'name': 'Collaborate well with others', 'items': [{'n': 39, 't': 'Push back to stakeholders above the team when needed'}, {'n': 40, 't': 'Work well with other teams or stakeholders'}]}, {'name': 'Communicate well to the organisation', 'items': [{'n': 41, 't': 'Are a united front on decisions, even if they disagree in private'}, {'n': 42, 't': 'Communicates its decisions to the organisation clearly and compellingly'}, {'n': 43, 't': 'Know when to share and when to hold back information with their respective teams'}, {'n': 44, 't': 'Share a compelling strategy and vision with their respective teams'}, {'n': 45, 't': 'Role model the right behaviours to the people and teams they lead'}, {'n': 46, 't': 'Show accessibility and collective visibility within the organisation'}]}]}]

OPEN=[('open_1','What does this team do really well?'),
      ('open_2',"What's the change that would make the biggest impact on team performance?"),
      ('open_3','What have we not asked you that you think is important?')]

def _c(h):
    h=h.lstrip('#'); return RGBColor(int(h[0:2],16),int(h[2:4],16),int(h[4:6],16))
NAVY=_c('20396D');GREEN=_c('8DC640');TEAL=_c('2295A0');RED=_c('EF4136')
MUT=_c('6B7280');INK=_c('1A1A1A');LIGHT=_c('F4F7FB');LINE=_c('E2E4E8');WHITE=_c('FFFFFF')
BUCKET=[_c('E23B33'),_c('F07B5B'),_c('F6C0B0'),_c('CDE3A6'),_c('97C93D'),_c('5FA02A')]
DIMC={d['key']:_c(d['colour']) for d in MODEL}
ITEMTEXT={it['n']:it['t'] for d in MODEL for s in d['subs'] for it in s['items']}
F='Poppins'

def _find(sl,n):
    for sh in sl.shapes:
        if sh.name==n: return sh
def _settext(sh,t):
    p=sh.text_frame.paragraphs[0]
    if p.runs:
        p.runs[0].text=t
        for r in p.runs[1:]: r.text=''
    else: p.text=t
def _box(sl,x,y,w,h,text,size,color,bold=False,italic=False,align=PP_ALIGN.LEFT,anchor=MSO_ANCHOR.TOP,line=1.2):
    tb=sl.shapes.add_textbox(Inches(x),Inches(y),Inches(w),Inches(h)); tf=tb.text_frame
    tf.word_wrap=True; tf.auto_size=MSO_AUTO_SIZE.NONE; tf.vertical_anchor=anchor; tf.text=text
    for p in tf.paragraphs:
        p.alignment=align; p.line_spacing=line
        for r in p.runs:
            r.font.size=Pt(size); r.font.color.rgb=color; r.font.bold=bold; r.font.italic=italic; r.font.name=F
    return tb
def _bar(sl,x,y,w,h,cats,vals,colors,catsize=8,labelsize=8,gap=60):
    cd=CategoryChartData(); cd.categories=cats; cd.add_series('Score',vals)
    gf=sl.shapes.add_chart(XL_CHART_TYPE.BAR_CLUSTERED,Inches(x),Inches(y),Inches(w),Inches(h),cd)
    ch=gf.chart; ch.has_legend=False; ch.has_title=False
    plot=ch.plots[0]; plot.has_data_labels=True; plot.gap_width=gap
    dl=plot.data_labels; dl.number_format='0.0'; dl.number_format_is_linked=False
    dl.position=XL_LABEL_POSITION.OUTSIDE_END; dl.font.size=Pt(labelsize); dl.font.name=F
    va=ch.value_axis; va.minimum_scale=1; va.maximum_scale=6
    va.tick_labels.font.size=Pt(7); va.tick_labels.font.name=F
    ca=ch.category_axis; ca.tick_labels.font.size=Pt(catsize); ca.tick_labels.font.name=F
    for i,pt in enumerate(plot.series[0].points):
        pt.format.fill.solid(); pt.format.fill.fore_color.rgb=colors[i%len(colors)]
def _stacked(sl,x,y,w,h,cats,series):
    cd=CategoryChartData(); cd.categories=cats
    labs=['Strongly disagree','Disagree','Slightly disagree','Slightly agree','Agree','Strongly agree']
    for i in range(6): cd.add_series(labs[i],[series[c][i] for c in range(len(cats))])
    gf=sl.shapes.add_chart(XL_CHART_TYPE.BAR_STACKED,Inches(x),Inches(y),Inches(w),Inches(h),cd)
    ch=gf.chart; ch.has_title=False; ch.has_legend=True
    ch.legend.position=XL_LEGEND_POSITION.BOTTOM; ch.legend.include_in_layout=False
    ch.legend.font.size=Pt(6.5); ch.legend.font.name=F
    plot=ch.plots[0]; plot.gap_width=40
    ca=ch.category_axis; ca.tick_labels.font.size=Pt(7); ca.tick_labels.font.name=F
    for si,s in enumerate(plot.series):
        s.format.fill.solid(); s.format.fill.fore_color.rgb=BUCKET[si]

def _phgeom(ph,sl):
    if ph.left is not None: return ph.left,ph.top,ph.width,ph.height
    for lp in sl.slide_layout.placeholders:
        if lp.placeholder_format.idx==ph.placeholder_format.idx:
            return lp.left,lp.top,lp.width,lp.height
    return None

def _insert_logo(slide, ph, logo_bytes):
    """Pad client logo onto a white canvas matching the panel aspect, then insert — robust for any logo."""
    g=_phgeom(ph,slide)
    ar=(g[2]/g[3]) if g else 0.87
    try:
        logo=Image.open(io.BytesIO(logo_bytes)).convert('RGBA')
    except Exception:
        return
    # Trim uniform white / transparent borders so the logo fills the panel.
    try:
        bbox=None
        px=logo.load(); W,H=logo.size
        minX,minY,maxX,maxY=W,H,-1,-1
        step=max(1,min(W,H)//400)  # sample for speed on large images
        for y in range(0,H,step):
            for x in range(0,W,step):
                r,gg,b,a=px[x,y]
                if a>24 and not(r>245 and gg>245 and b>245):
                    if x<minX:minX=x
                    if x>maxX:maxX=x
                    if y<minY:minY=y
                    if y>maxY:maxY=y
        if maxX>minX and maxY>minY:
            pad=int(max(maxX-minX,maxY-minY)*0.04)
            box=(max(0,minX-pad),max(0,minY-pad),min(W,maxX+pad),min(H,maxY+pad))
            logo=logo.crop(box)
    except Exception:
        pass
    CW=1200; CH=max(1,int(CW/ar))
    canvas=Image.new('RGBA',(CW,CH),(255,255,255,255))
    scale=min(CW*0.50/logo.width, CH*0.50/logo.height)
    nw,nh=max(1,int(logo.width*scale)),max(1,int(logo.height*scale))
    canvas.alpha_composite(logo.resize((nw,nh),Image.LANCZOS),((CW-nw)//2,(CH-nh)//2))
    tmp=io.BytesIO(); canvas.convert('RGB').save(tmp,'PNG'); tmp.seek(0)
    ph.insert_picture(tmp)

def build_deck(p):
    prs=Presentation(io.BytesIO(base64.b64decode(TEMPLATE_B64))); S=prs.slides
    cname=p.get('clientName') or ''
    date=p.get('date') or ''
    teamN=int(p.get('teamN',0)); stakeN=int(p.get('stakeN',0))
    ov=p.get('overall',{}); areaMeans=p.get('areaMeans',{}); subMeans=p.get('subMeans',{})
    itemMean=p.get('itemMean',{}); itemDist=p.get('itemDist',{}); verb=p.get('verbatim',{})
    def im(n): return float(itemMean.get(str(n), itemMean.get(n, 0)) or 0)
    def idist(n): return itemDist.get(str(n), itemDist.get(n, [0]*6)) or [0]*6

    # 1 COVER
    s=S[0]
    tsh=_find(s,'Title 3')
    tf=tsh.text_frame; tf.clear()
    from pptx.util import Pt as _Pt
    p0=tf.paragraphs[0]; p0.alignment=PP_ALIGN.LEFT
    r0=p0.add_run(); r0.text='HIGH PERFORMING LEADERSHIP TEAMS'
    r0.font.size=_Pt(9); r0.font.bold=True; r0.font.color.rgb=WHITE; r0.font.name=F
    try: p0.space_after=_Pt(4)
    except Exception: pass
    p1=tf.add_paragraph(); p1.alignment=PP_ALIGN.LEFT
    r1=p1.add_run(); r1.text='HPLT'
    r1.font.size=_Pt(40); r1.font.bold=True; r1.font.color.rgb=WHITE; r1.font.name=F
    _settext(_find(s,'Subtitle 4'),cname)
    _settext(_find(s,'Text Placeholder 6'),date)
    logo_du=p.get('clientLogo') or ''
    ph=_find(s,'Picture Placeholder 1')
    if logo_du and ph is not None and ',' in logo_du:
        try: _insert_logo(s, ph, base64.b64decode(logo_du.split(',',1)[1]))
        except Exception: pass

    # 2 EXPLAINER — rebuild as clean headings + body (drop the uniform bullet wall)
    s=S[1]
    tp=_find(s,'Text Placeholder 2')
    if tp is not None: tp._element.getparent().remove(tp._element)
    qa=[('What is this tool?',
         'The High Performing Leadership Teams (HPLT) Diagnostic. It measures the extent to which people feel your team shows the five traits that define a high-performing leadership team — described in full on the next page.'),
        ('What data have we gathered?',
         'Team members rated their agreement with 46 statements across the five traits, from 1 (strongly disagree) to 6 (strongly agree), plus three open questions and a final 1–10 rating of overall performance. External stakeholders answered the overall rating and the three open questions.'),
        ('Who completed?',
         '%d team members and %d external stakeholders completed the diagnostic.'%(teamN,stakeN)),
        ('How will we use this report?',
         'Team members read and reflect on the results. A facilitated conversation then helps the team make sense of them together and identify next steps.')]
    y=1.05
    for q,ans in qa:
        _box(s,0.5,y,9.0,0.32,q,12,NAVY,bold=True)
        tb=_box(s,0.5,y+0.34,9.0,0.9,ans,9.5,MUT,line=1.25)
        # estimate lines to advance y (roughly 108 chars per line at this width/size)
        import math
        lines=max(1,math.ceil(len(ans)/108))
        y+=0.34+lines*0.235+0.28

    # 3 WHAT WE MEASURE — rebuild natively (drop template's flawed image)
    s=S[2]
    for sh in list(s.shapes):
        if sh.shape_type==13 or sh.name.startswith('Picture'):
            sh._element.getparent().remove(sh._element)
    y=1.05
    for i,d in enumerate(MODEL):
        col=DIMC[d['key']]
        chip=s.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE,Inches(0.5),Inches(y),Inches(0.42),Inches(0.42))
        chip.fill.solid(); chip.fill.fore_color.rgb=col; chip.line.fill.background(); chip.shadow.inherit=False
        ctf=chip.text_frame
        for m in ('margin_left','margin_right','margin_top','margin_bottom'): setattr(ctf,m,0)
        ctf.text='0%d'%(i+1)
        for para in ctf.paragraphs:
            para.alignment=PP_ALIGN.CENTER
            for r in para.runs: r.font.size=Pt(10); r.font.bold=True; r.font.color.rgb=WHITE; r.font.name=F
        _box(s,1.05,y-0.05,8.4,0.35,d['name'],13,col,bold=True)
        _box(s,1.05,y+0.32,8.4,0.35,d['desc'],8.5,MUT)
        _box(s,1.05,y+0.62,8.4,0.3,'   ·   '.join(su['name'] for su in d['subs']),8,INK,italic=True)
        y+=0.86

    # 5 OVERALL
    s=S[4]
    for i,(lab,val,col) in enumerate([('All',ov.get('all',0),NAVY),('Team members',ov.get('team',0),GREEN),('Stakeholders',ov.get('stake',0),TEAL)]):
        x=0.5+i*3.05
        r=s.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE,Inches(x),Inches(1.9),Inches(2.75),Inches(1.85))
        r.fill.solid(); r.fill.fore_color.rgb=LIGHT; r.line.color.rgb=LINE; r.line.width=Pt(1); r.shadow.inherit=False
        _box(s,x,2.05,2.75,0.8,('%.1f'%float(val or 0)),30,col,bold=True,align=PP_ALIGN.CENTER)
        _box(s,x,2.9,2.75,0.3,'out of 10',9,MUT,align=PP_ALIGN.CENTER)
        _box(s,x,3.2,2.75,0.35,lab,11,NAVY,bold=True,align=PP_ALIGN.CENTER)
    _box(s,0.5,4.1,9,0.4,'How team members and external stakeholders rate the team\u2019s overall performance (1\u201310).',9,MUT)

    # 6 FIVE AREAS (ranked)
    ranked=sorted(MODEL,key=lambda d:-(areaMeans.get(d['key'],0) or 0))
    _bar(S[5],0.4,1.0,9.2,4.1,[d['name'] for d in ranked],[round(areaMeans.get(d['key'],0) or 0,1) for d in ranked],[DIMC[d['key']] for d in ranked],catsize=9,labelsize=9,gap=70)

    # 7 SUB-AREAS (14)
    snames=[];svals=[];scols=[]
    for d in MODEL:
        for su in d['subs']:
            snames.append(su['name']); svals.append(round(subMeans.get(su['name'],0) or 0,1)); scols.append(DIMC[d['key']])
    _bar(S[6],0.4,0.95,9.2,4.35,snames,svals,scols,catsize=7,labelsize=7,gap=30)

    # 8 HIGHEST/LOWEST
    flat=sorted([(im(n),n) for n in ITEMTEXT], key=lambda z:-z[0])
    top=flat[:5]; bottom=list(reversed(flat[-5:]))
    s=S[7]
    _box(s,0.5,1.05,4.4,0.35,'Highest scoring',11,GREEN,bold=True)
    _box(s,0.5,1.45,4.6,3,'\n'.join('%s   (%.1f)'%(ITEMTEXT[n],mn) for mn,n in top),9,INK,line=1.5)
    _box(s,5.1,1.05,4.4,0.35,'Lowest scoring',11,RED,bold=True)
    _box(s,5.1,1.45,4.6,3,'\n'.join('%s   (%.1f)'%(ITEMTEXT[n],mn) for mn,n in bottom),9,INK,line=1.5)

    # 10-14 PER-AREA DISTRIBUTIONS
    for di,d in enumerate(MODEL):
        its=[it for su in d['subs'] for it in su['items']]
        cats=[(it['t'][:30]+'\u2026') if len(it['t'])>30 else it['t'] for it in its]
        _stacked(S[9+di],0.4,0.95,9.2,4.25,cats,[idist(it['n']) for it in its])

    # 16-18 VERBATIM
    for qi,(k,q) in enumerate(OPEN):
        s=S[15+qi]
        tt=(verb.get(k,{}) or {}).get('team',[]) or []
        ts=(verb.get(k,{}) or {}).get('stake',[]) or []
        _box(s,0.5,1.0,4.4,0.35,'Team members (%d)'%len(tt),10,GREEN,bold=True)
        _box(s,0.5,1.4,4.4,4.0,'\n\n'.join('\u201c'+t+'\u201d' for t in tt) or 'No responses',8.5,INK,line=1.3)
        _box(s,5.1,1.0,4.4,0.35,'Stakeholders (%d)'%len(ts),10,TEAL,bold=True)
        _box(s,5.1,1.4,4.4,4.0,'\n\n'.join('\u201c'+t+'\u201d' for t in ts) or 'No responses',8.5,INK,line=1.3)

    # SAFETY: if no team members completed, the team-only views have no data.
    # Overlay a clear note so those slides read as "awaiting responses" rather than blank.
    if teamN==0:
        note='Awaiting team-member responses — this view populates once team members complete the diagnostic.'
        for idx in (5,6,7,9,10,11,12,13):
            try:
                nb=_box(S[idx],1.3,2.4,7.4,0.9,note,12,MUT,align=PP_ALIGN.CENTER,anchor=MSO_ANCHOR.MIDDLE,line=1.3)
                nb.fill.solid(); nb.fill.fore_color.rgb=WHITE
            except Exception: pass

    # CLOSING (last slide) — remove the template's empty "Sign off" / "Mission statement"
    # placeholders (their prompt text was showing through), leave a clean statement.
    s=S[21]
    for nm in ('Title 1','Subtitle 2'):
        sh=_find(s,nm)
        if sh is not None: sh._element.getparent().remove(sh._element)
    _box(S[21],1.6,1.9,6.8,2.0,'At AhaMo, we partner with you to drive personal and organisational transformation. We understand that lasting change comes from within, which is why we\u2019ve designed a comprehensive suite of services focused on empowering your leaders and teams.',13,WHITE,align=PP_ALIGN.CENTER,anchor=MSO_ANCHOR.MIDDLE,line=1.3)

    # Drop redundant slide 21 (index 20)
    lst=prs.slides._sldIdLst; ids=list(lst)
    if len(ids)>=21: lst.remove(ids[20])

    out=io.BytesIO(); prs.save(out); out.seek(0)
    return out.read()


TEMPLATE_B64 = ""


# ---- Vercel serverless handler ----
import json as _json
from http.server import BaseHTTPRequestHandler
class handler(BaseHTTPRequestHandler):
    def do_POST(self):
        try:
            length=int(self.headers.get('content-length',0))
            payload=_json.loads(self.rfile.read(length) or b'{}')
            data=build_deck(payload)
            fname=(payload.get('clientName') or 'HPLT').replace(' ','_')+'-HPLT-Report.pptx'
            self.send_response(200)
            self.send_header('Content-Type','application/vnd.openxmlformats-officedocument.presentationml.presentation')
            self.send_header('Content-Disposition','attachment; filename="%s"'%fname)
            self.send_header('Content-Length',str(len(data)))
            self.end_headers(); self.wfile.write(data)
        except Exception as e:
            self.send_response(500); self.send_header('Content-Type','application/json'); self.end_headers()
            self.wfile.write(_json.dumps({'error':str(e)}).encode())
    def do_GET(self):
        self.send_response(200)
        self.send_header('Content-Type','application/json'); self.end_headers()
        self.wfile.write(_json.dumps({'ok':True,'service':'hplt2-deck','msg':'Ready. POST session data to generate a deck.'}).encode())
